var updateAuthorProfileRequestParser = aip.MustNewUpdateRequestParser[*v12.UpdateAuthorProfileRequest, *v14.AuthorProfile]()

func (s *libraryService_AuthorProfileServer) UpdateAuthorProfile(ctx context.Context, request *v12.UpdateAuthorProfileRequest) (*v14.AuthorProfile, error) {
	for {
		response, err := s.updateAuthorProfile(ctx, request)
		if err != nil {
			if request.GetAuthorProfile().GetEtag() == "" && status.HasCode(err, codes.Aborted) {
				// Request did not specify an ETag => we retry.
				// In order to understand why we still use ETag in the db layer, consider the following situation:
				//  > `resource.metadata` is stored as JSONB in the store.
				//  > Request A wants to update `resource.metadata.field1` and does not care about ETag.
				//  > Request B wants to update `resource.metadata.field2` and does not care about ETag.
				//  > Request A reads the resource and patches it.
				//  > Request B reads the resource and patches it.
				//  > Request A persists the patched resource, followed by Request B.
				//  > Request A's changes are lost.
				select {
				case <-ctx.Done():
					return nil, status.Errorf(codes.Canceled, "context canceled while retrying update").Err()
				default:
					continue
				}
			}
			return nil, err
		}
		return response, nil
	}
}

func (s *libraryService_AuthorProfileServer) updateAuthorProfile(ctx context.Context, request *v12.UpdateAuthorProfileRequest) (*v14.AuthorProfile, error) {
	if len(request.GetUpdateMask().GetPaths()) == 0 {
		return nil, status.Errorf(codes.InvalidArgument, "missing update_mask.paths").Err()
	}
	if resourcename.ContainsWildcard(request.AuthorProfile.Name) {
		return nil, status.Errorf(codes.InvalidArgument, "cannot use wildcard").Err()
	}

	// STEP 1: Parse request.
	parsedRequest, err := updateAuthorProfileRequestParser.Parse(request)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "parsing request: %v", err).Err()
	}

	// STEP 2: retrieve existing resource.
	getAuthorProfileRequest := &v12.GetAuthorProfileRequest{Name: request.AuthorProfile.Name}
	existingAuthorProfile, err := s.GetAuthorProfile(ctx, getAuthorProfileRequest)
	if err != nil {
		return nil, err
	}
	// Verify that the resource is not soft deleted
	if existingAuthorProfile.DeleteTime != nil {
		return nil, status.Errorf(codes.NotFound, "authorProfile does not exist").Err()
	}
	// Capture the Etag. If it is not set, use the latest available Etag.
	etag := request.GetAuthorProfile().GetEtag()
	if etag == "" {
		etag = existingAuthorProfile.GetEtag()
	}

	// STEP 3: Patch the existing resource.
	patchedAuthorProfile := proto.CloneOf(existingAuthorProfile)
	parsedRequest.ApplyFieldMask(patchedAuthorProfile, request.AuthorProfile)
	if err := protovalidate.Validate(patchedAuthorProfile); err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "validating patched resource: %v", err).Err()
	}

	// Set the update time.
	patchedAuthorProfile.UpdateTime = timestamppb.Now()
	{ // Compute the new Etag.
		var err error
		patchedAuthorProfile.Etag, err = aip.ComputeETag(patchedAuthorProfile)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "computing new etag: %v", err).Err()
		}
	}

	// STEP 4: Insert patched resource.
	authorProfileModel, err := model.AuthorProfileFromPb(patchedAuthorProfile)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "converting authorProfile from pb to model: %v", err).Err()
	}
	dbAuthorProfileModel, err := s.store.UpdateAuthorProfile(ctx, authorProfileModel, parsedRequest.GetSQLUpdateClause(), parsedRequest.GetSQLColumns(), etag)
	if err != nil {
		if errors.Is(err, model.ErrAuthorProfileNotExist) {
			return nil, status.Errorf(codes.NotFound, "authorProfile does not exist").Err()
		}
		if errors.Is(err, model.ErrAuthorProfileETagChanged) {
			return nil, status.Errorf(codes.Aborted, "ETag changed").Err()
		}
		return nil, status.FromError(err, "updating authorProfile").Err()
	}

	authorProfile, err := dbAuthorProfileModel.ToPb()
	if err != nil {
		return nil, status.Errorf(codes.Internal, "converting authorProfile from model to pb: %v", err).Err()
	}

	return authorProfile, nil
}

