func (s *libraryService_AuthorProfileServer) BatchGetAuthorProfiles(ctx context.Context, request *v12.BatchGetAuthorProfilesRequest) (*v12.BatchGetAuthorProfilesResponse, error) {
	var organizationId, authorId string
	if request.Parent != "" {
		if err := resourcename.Sscan(request.Parent, "organizations/{organization}/authors/{author}", &organizationId, &authorId); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "invalid parent name: %v", err).Err()
		}
	}

	organizationIds := make([]string, len(request.GetNames()))
	authorIds := make([]string, len(request.GetNames()))

	for i, name := range request.Names {
		if resourcename.ContainsWildcard(name) {
			return nil, status.Errorf(codes.InvalidArgument, "name cannot contain wildcard").Err()
		}
		if request.Parent != "" && !resourcename.HasParent(name, request.Parent) {
			return nil, status.Errorf(codes.InvalidArgument, "name %q does not have parent %q", name, request.Parent).Err()
		}
		organizationId, authorId, err := model.ParseAuthorProfileName(name)
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "parsing name %s: %v", name, err).Err()
		}
		organizationIds[i] = organizationId
		authorIds[i] = authorId
	}

	dbAuthorProfiles, err := s.store.BatchGetAuthorProfiles(ctx, organizationIds, authorIds)
	if err != nil {
		return nil, status.FromError(err, "batch getting author_profile").Err()
	}
	if len(dbAuthorProfiles) != len(request.Names) {
		return nil, status.Errorf(codes.NotFound, "expected %d authorProfiles, found %d", len(request.Names), len(dbAuthorProfiles)).Err()
	}

	authorProfileNameToAuthorProfile := make(map[string]*v14.AuthorProfile, len(request.Names))
	for _, dbAuthorProfileModel := range dbAuthorProfiles {
		authorProfile, err := dbAuthorProfileModel.ToPb()
		if err != nil {
			return nil, status.Errorf(codes.Internal, "converting authorProfile from model to pb: %v", err).Err()
		}
		authorProfileNameToAuthorProfile[authorProfile.Name] = authorProfile
	}

	authorProfiles := make([]*v14.AuthorProfile, 0, len(dbAuthorProfiles))
	for _, name := range request.Names {
		authorProfile, ok := authorProfileNameToAuthorProfile[name]
		if !ok {
			return nil, status.Errorf(codes.NotFound, "could not find %q", name).Err()
		}
		authorProfiles = append(authorProfiles, authorProfile)
	}

	return &v12.BatchGetAuthorProfilesResponse{
		AuthorProfiles: authorProfiles,
	}, nil
}

