func (s *libraryService_ShelfServer) DeleteShelf(ctx context.Context, request *v12.DeleteShelfRequest) (*v14.Shelf, error) {
	if resourcename.ContainsWildcard(request.Name) {
		return nil, status.Errorf(codes.InvalidArgument, "cannot use wildcard").Err()
	}

	// STEP 1: Parse resource name.
	organizationId, shelfId, err := model.ParseShelfName(request.Name)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "parsing name: %v", err).Err()
	}

	deleteTime := time.Now().UTC()
	// STEP 2: Soft delete the resource.
	dbShelfModel, err := s.store.SoftDeleteShelf(ctx, organizationId, shelfId, request.GetForce(), deleteTime)
	if err != nil {
		if errors.Is(err, model.ErrShelfNotExist) {
			return nil, status.Errorf(codes.NotFound, "shelf does not exist").Err()
		}
		if errors.Is(err, model.ErrShelfHasChildren) {
			return nil, status.Errorf(codes.FailedPrecondition, "shelf has child resources; set force to delete them too").Err()
		}
		if errors.Is(err, model.ErrShelfAlreadyDeleted) {
			if request.AllowMissing {
				getShelfRequest := &v12.GetShelfRequest{Name: request.Name}
				shelf, err := s.GetShelf(ctx, getShelfRequest)
				if err != nil {
					return nil, err
				}
				if err := s.publishResourceDeletedEvent(ctx, shelf); err != nil {
					return nil, err
				}
				return shelf, nil
			}
			return nil, status.Errorf(codes.NotFound, "shelf already deleted").Err()
		}
		return nil, status.FromError(err, "soft deleting shelf").Err()
	}

	// STEP 3: Convert to protobuf and return.
	shelf, err := dbShelfModel.ToPb()
	if err != nil {
		return nil, status.Errorf(codes.Internal, "converting shelf from model to pb: %v", err).Err()
	}

	// STEP 4: Publish event.
	if err := s.publishResourceDeletedEvent(ctx, shelf); err != nil {
		return nil, err
	}

	return shelf, nil
}

func (s *libraryService_ShelfServer) publishResourceUndeletedEvent(ctx context.Context, shelf *v14.Shelf) error {
	{
		subject := v14.GetShelfStream().GetUndeletedSubject()
		if err := subject.Publish(ctx, s.natsClient, shelf); err != nil {
			return status.Errorf(codes.Internal, "publishing undeleted event: %v", err).Err()
		}
	}
	return nil
}

func (s *libraryService_ShelfServer) UndeleteShelf(ctx context.Context, request *v12.UndeleteShelfRequest) (*v14.Shelf, error) {
	if resourcename.ContainsWildcard(request.Name) {
		return nil, status.Errorf(codes.InvalidArgument, "cannot use wildcard").Err()
	}

	// STEP 1: Parse resource name.
	organizationId, shelfId, err := model.ParseShelfName(request.Name)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "parsing name: %v", err).Err()
	}

	// STEP 2: Undelete the resource.
	dbShelfModel, err := s.store.UndeleteShelf(ctx, organizationId, shelfId)
	if err != nil {
		if errors.Is(err, model.ErrShelfNotExist) {
			return nil, status.Errorf(codes.NotFound, "shelf does not exist").Err()
		}
		if errors.Is(err, model.ErrShelfNotDeleted) {
			return nil, status.Errorf(codes.AlreadyExists, "shelf is not deleted").Err()
		}
		return nil, status.FromError(err, "undeleting shelf").Err()
	}

	// STEP 3: Convert to protobuf and return.
	shelf, err := dbShelfModel.ToPb()
	if err != nil {
		return nil, status.Errorf(codes.Internal, "converting shelf from model to pb: %v", err).Err()
	}

	// STEP 4: Publish event.
	if err := s.publishResourceUndeletedEvent(ctx, shelf); err != nil {
		return nil, err
	}

	return shelf, nil
}

var listShelvesRequestParser = aip.MustNewListRequestParser[*v12.ListShelvesRequest, *v14.Shelf](aip.WithFilteringOpts(aip.WithFQN()), aip.WithOrderingOpts(aip.WithOrderingFQN()))

func (s *libraryService_ShelfServer) ListShelves(ctx context.Context, request *v12.ListShelvesRequest) (*v12.ListShelvesResponse, error) {
	// Parse parent names
	var organizationId string
	if err := resourcename.Sscan(request.Parent, "organizations/{organization}", &organizationId); err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "invalid parent name: %v", err).Err()
	}

	// Parse request
	parsedRequest, err := listShelvesRequestParser.Parse(request)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, err.Error()).Err()
	}
	whereClause, whereParams := parsedRequest.GetSQLWhereClause()
	var dbColumns []string

	// Retrieve from the database.
	dbShelfs, err := s.store.ListShelves(ctx, organizationId, request.ShowDeleted, whereClause, parsedRequest.GetSQLOrderByClause(), parsedRequest.GetSQLPaginationClause(), dbColumns, whereParams...)
	if err != nil {
		return nil, status.FromError(err, "listing shelves").Err()
	}
	nextPageToken := parsedRequest.GetNextPageToken(len(dbShelfs))
	if nextPageToken != "" {
		dbShelfs = dbShelfs[:len(dbShelfs)-1]
	}

	// Convert back to proto.
	shelves := make([]*v14.Shelf, 0, len(dbShelfs))
	for _, dbShelf := range dbShelfs {
		shelf, err := dbShelf.ToPb()
		if err != nil {
			return nil, status.Errorf(codes.Internal, "converting model.Shelf to Shelf: %v", err).Err()
		}
		shelves = append(shelves, shelf)
	}

	// Create and return response.
	return &v12.ListShelvesResponse{
		Shelves:       shelves,
		NextPageToken: nextPageToken,
	}, nil
}

func (s *libraryService_ShelfServer) BatchCreateShelves(ctx context.Context, request *v12.BatchCreateShelvesRequest) (*v12.BatchCreateShelvesResponse, error) {
	if resourcename.ContainsWildcard(request.Parent) {
		return nil, status.Errorf(codes.InvalidArgument, "parent cannot contain wildcard").Err()
	}
	n := len(request.Requests)
	requestIDs := make([]string, 0, n)
	requestIDSet := make(map[string]struct{}, n)
	shelfModels := make([]*model.Shelf, 0, n)
	names := make(map[string]struct{}, n)
	for i, createRequest := range request.Requests {
		// A sub-request inherits the batch parent; an explicit one must agree.
		if request.Parent != "" {
			if createRequest.Parent == "" {
				createRequest.Parent = request.Parent
			} else if createRequest.Parent != request.Parent {
				return nil, status.Errorf(codes.InvalidArgument, "requests[%d].parent %q does not match parent %q", i, createRequest.Parent, request.Parent).Err()
			}
		}
		if createRequest.ValidateOnly {
			return nil, status.Errorf(codes.InvalidArgument, "requests[%d].validate_only is not supported", i).Err()
		}
		shelfModel, err := s.prepareCreateShelf(ctx, createRequest)
		if err != nil {
			return nil, status.FromError(err, "requests[%d]", i).Err()
		}
		if _, ok := names[createRequest.Shelf.Name]; ok {
			return nil, status.Errorf(codes.InvalidArgument, "requests[%d]: duplicate shelf name %q", i, createRequest.Shelf.Name).Err()
		}
		names[createRequest.Shelf.Name] = struct{}{}
		if _, ok := requestIDSet[createRequest.RequestId]; ok {
			return nil, status.Errorf(codes.InvalidArgument, "requests[%d]: duplicate request_id %q", i, createRequest.RequestId).Err()
		}
		requestIDSet[createRequest.RequestId] = struct{}{}
		requestIDs = append(requestIDs, createRequest.RequestId)
		shelfModels = append(shelfModels, shelfModel)
	}

	// Insert the whole batch atomically.
	dbShelves, err := s.store.BatchInsertShelves(ctx, requestIDs, shelfModels)
	if err != nil {
		if errors.Is(err, model.ErrShelfAlreadyExists) {
			return nil, status.Errorf(codes.AlreadyExists, "shelf already exists").Err()
		}
		return nil, status.FromError(err, "inserting shelves").Err()
	}
	if len(dbShelves) != n {
		return nil, status.Errorf(codes.Internal, "expected %d inserted shelves, got %d", n, len(dbShelves)).Err()
	}

	shelves := make([]*v14.Shelf, n)
	for i, dbShelfModel := range dbShelves {
		shelf, err := dbShelfModel.ToPb()
		if err != nil {
			return nil, status.Errorf(codes.Internal, "converting shelf from model to pb: %v", err).Err()
		}
		shelves[i] = shelf
	}

	for _, shelf := range shelves {
		// STEP 5: Publish events.
		{
			subject := v14.GetShelfStream().GetCreatedSubject()
			if err := subject.Publish(ctx, s.natsClient, shelf); err != nil {
				return nil, status.Errorf(codes.Internal, "publishing created event: %v", err).Err()
			}
		}
	}

	return &v12.BatchCreateShelvesResponse{Shelves: shelves}, nil
}

func (s *libraryService_ShelfServer) BatchGetShelves(ctx context.Context, request *v12.BatchGetShelvesRequest) (*v12.BatchGetShelvesResponse, error) {
	var organizationId string
	if request.Parent != "" {
		if err := resourcename.Sscan(request.Parent, "organizations/{organization}", &organizationId); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "invalid parent name: %v", err).Err()
		}
	}

	organizationIds := make([]string, len(request.GetNames()))
	shelfIds := make([]string, len(request.GetNames()))

	for i, name := range request.Names {
		if resourcename.ContainsWildcard(name) {
			return nil, status.Errorf(codes.InvalidArgument, "name cannot contain wildcard").Err()
		}
		if request.Parent != "" && !resourcename.HasParent(name, request.Parent) {
			return nil, status.Errorf(codes.InvalidArgument, "name %q does not have parent %q", name, request.Parent).Err()
		}
		organizationId, shelfId, err := model.ParseShelfName(name)
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "parsing name %s: %v", name, err).Err()
		}
		organizationIds[i] = organizationId
		shelfIds[i] = shelfId
	}

	dbShelves, err := s.store.BatchGetShelves(ctx, organizationIds, shelfIds)
	if err != nil {
		return nil, status.FromError(err, "batch getting shelf").Err()
	}
	if len(dbShelves) != len(request.Names) {
		return nil, status.Errorf(codes.NotFound, "expected %d shelves, found %d", len(request.Names), len(dbShelves)).Err()
	}

	shelfNameToShelf := make(map[string]*v14.Shelf, len(request.Names))
	for _, dbShelfModel := range dbShelves {
		shelf, err := dbShelfModel.ToPb()
		if err != nil {
			return nil, status.Errorf(codes.Internal, "converting shelf from model to pb: %v", err).Err()
		}
		shelfNameToShelf[shelf.Name] = shelf
	}

	shelves := make([]*v14.Shelf, 0, len(dbShelves))
	for _, name := range request.Names {
		shelf, ok := shelfNameToShelf[name]
		if !ok {
			return nil, status.Errorf(codes.NotFound, "could not find %q", name).Err()
		}
		shelves = append(shelves, shelf)
	}

	return &v12.BatchGetShelvesResponse{
		Shelves: shelves,
	}, nil
}

type libraryService_BookStore interface {
	BatchInsertBooks(ctx context.Context, requestIDs []string, books []*model.Book, bookReviews []*model.BookReview) ([]*model.Book, error)
	UpdateBook(ctx context.Context, book *model.Book, updateClause string, columns []string, etag string) (*model.Book, error)
	DeleteBook(ctx context.Context, organizationId, shelfId, bookId string, etag string, force bool) (*model.Book, error)
	GetBook(ctx context.Context, organizationId, shelfId, bookId string) (*model.Book, error)
	BatchGetBooks(ctx context.Context, organizationIds []string, shelfIds []string, bookIds []string) ([]*model.Book, error)
	ListBooks(ctx context.Context, organizationId, shelfId string, whereClause, orderByClause, paginationClause string, dbColumns []string, whereParams ...any) ([]*model.Book, error)
	SearchBooks(ctx context.Context, organizationId, shelfId string, includeSnippets bool, tsQuery, whereClause, paginationClause string, dbColumns []string, whereParams ...any) ([]*model.Book, []map[string]string, error)
}

type libraryService_BookServer struct {
	store      libraryService_BookStore
	natsClient *nats.Client
}

func newLibraryService_BookServer(store libraryService_BookStore, natsClient *nats.Client) *libraryService_BookServer {
	return &libraryService_BookServer{
		store:      store,
		natsClient: natsClient,
	}
}

func (s *libraryService_BookServer) prepareCreateBook(ctx context.Context, request *v12.CreateBookRequest) (*model.Book, *model.BookReview, error) {
	// STEP 1: Set identifiers.
	if request.RequestId == "" { // We always set a request id
		request.RequestId = uuid.MustNewV7().String()
	}
	bookId := request.BookId
	if bookId == "" {
		bookId = aip.NewSystemGeneratedBase32ResourceID()
	}

	var organizationId, shelfId string
	if resourcename.ContainsWildcard(request.Parent) {
		return nil, nil, status.Errorf(codes.InvalidArgument, "parent cannot contain wildcard").Err()
	}
	if err := resourcename.Sscan(request.Parent, "organizations/{organization}/shelves/{shelf}", &organizationId, &shelfId); err != nil {
		return nil, nil, status.Errorf(codes.InvalidArgument, "invalid parent name: %v", err).Err()
	}

	request.Book.Name = resourcename.Sprint("organizations/{organization}/shelves/{shelf}/books/{book}", organizationId, shelfId, bookId)

	// STEP 2: Instantiate timestamps.
	// Check for x-migration-request header
	if values := metadata.ValueFromIncomingContext(ctx, "x-migration-request"); len(values) > 0 {
		if request.Book.CreateTime == nil {
			return nil, nil, status.Errorf(codes.InvalidArgument, "x-migration-request used without setting a create_time").Err()
		}
	} else {
		request.Book.CreateTime = timestamppb.Now()
	}
	request.Book.UpdateTime = request.Book.CreateTime

	{ // Capture the Etag.
		var err error
		request.Book.Etag, err = aip.ComputeETag(request.Book)
		if err != nil {
			return nil, nil, status.Errorf(codes.Internal, "computing etag: %v", err).Err()
		}
	}

	// STEP 3: Convert the resource to the database representation.
	bookModel, err := model.BookFromPb(request.Book)
	if err != nil {
		return nil, nil, status.Errorf(codes.Internal, "converting book from pb to model: %v", err).Err()
	}

	bookReview := &v14.BookReview{
		Name:       resourcename.Sprint("organizations/{organization}/shelves/{shelf}/books/{book}/review", organizationId, shelfId, bookId),
		CreateTime: request.Book.CreateTime,
		UpdateTime: request.Book.UpdateTime,
	}
	{
		var err error
		bookReview.Etag, err = aip.ComputeETag(bookReview)
		if err != nil {
			return nil, nil, status.Errorf(codes.Internal, "computing %s etag: %v", "bookReview", err).Err()
		}
	}
	bookReviewModel, err := model.BookReviewFromPb(bookReview)
	if err != nil {
		return nil, nil, status.Errorf(codes.Internal, "converting bookReview from pb to model: %v", err).Err()
	}

	return bookModel, bookReviewModel, nil
}

func (s *libraryService_BookServer) CreateBook(ctx context.Context, request *v12.CreateBookRequest) (*v14.Book, error) {
	bookModel, bookReviewModel, err := s.prepareCreateBook(ctx, request)
	if err != nil {
		return nil, err
	}

	if request.ValidateOnly {
		return request.Book, nil
	}

	// STEP 4: Insert the resource.
	dbBooks, err := s.store.BatchInsertBooks(ctx, []string{request.RequestId}, []*model.Book{bookModel}, []*model.BookReview{bookReviewModel})
	if err != nil {
		if errors.Is(err, model.ErrBookAlreadyExists) {
			return nil, status.Errorf(codes.AlreadyExists, "book already exists").Err()
		}
		return nil, status.FromError(err, "inserting books").Err()
	}
	if len(dbBooks) != 1 {
		return nil, status.Errorf(codes.Internal, "expected 1 inserted book, got %d", len(dbBooks)).Err()
	}

	book, err := dbBooks[0].ToPb()
	if err != nil {
		return nil, status.Errorf(codes.Internal, "converting book from model to pb: %v", err).Err()
	}

	return book, nil
}

func (s *libraryService_BookServer) GetBook(ctx context.Context, request *v12.GetBookRequest) (*v14.Book, error) {
	if resourcename.ContainsWildcard(request.Name) {
		return nil, status.Errorf(codes.InvalidArgument, "cannot use wildcard").Err()
	}

	organizationId, shelfId, bookId, err := model.ParseBookName(request.Name)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "parsing name: %v", err).Err()
	}

	// Retrieve from the database.
	dbBookModel, err := s.store.GetBook(ctx, organizationId, shelfId, bookId)
	if err != nil {
		if errors.Is(err, model.ErrBookNotExist) {
			return nil, status.Errorf(codes.NotFound, "book does not exist").Err()
		}
		return nil, status.FromError(err, "getting book").Err()
	}

	book, err := dbBookModel.ToPb()
	if err != nil {
		return nil, status.Errorf(codes.Internal, "converting book from model to pb: %v", err).Err()
	}
	return book, nil
}

var updateBookRequestParser = aip.MustNewUpdateRequestParser[*v12.UpdateBookRequest, *v14.Book]()

var updateBookCELEnv = func() *cel.Env {
	env, err := cel.NewEnv(
		ext.Protos(),
		cel.Types(&v14.Book{}),
		cel.Variable("previous_book", cel.ObjectType("malonaz.test.library.v1.Book")),
		cel.Variable("book", cel.ObjectType("malonaz.test.library.v1.Book")),
	)
	if err != nil {
		panic(fmt.Sprintf("creating update Book CEL environment: %v", err))
	}
	return env
}()

func (s *libraryService_BookServer) UpdateBook(ctx context.Context, request *v12.UpdateBookRequest) (*v14.Book, error) {
	for {
		response, err := s.updateBook(ctx, request)
		if err != nil {
			if request.GetBook().GetEtag() == "" && status.HasCode(err, codes.Aborted) {
				// Request did not specify an ETag => we retry.
				// In order to understand why we still use ETag in the db layer, consider the following situation:
				//  > `resource.metadata` is stored as JSONB in the store.
				//  > Request A wants to update `resource.metadata.field1` and does not care about ETag.
				//  > Request B wants to update `resource.metadata.field2` and does not care about ETag.
				//  > Request A reads the resource and patches it.
				//  > Request B reads the resource and patches it.
				//  > Request A persists the patched resource, followed by Request B.
				//  > Request A's changes are lost.
				select {
				case <-ctx.Done():
					return nil, status.Errorf(codes.Canceled, "context canceled while retrying update").Err()
				default:
					continue
				}
			}
			return nil, err
		}
		return response, nil
	}
}

func (s *libraryService_BookServer) updateBook(ctx context.Context, request *v12.UpdateBookRequest) (*v14.Book, error) {
	if len(request.GetUpdateMask().GetPaths()) == 0 {
		return nil, status.Errorf(codes.InvalidArgument, "missing update_mask.paths").Err()
	}
	if resourcename.ContainsWildcard(request.Book.Name) {
		return nil, status.Errorf(codes.InvalidArgument, "cannot use wildcard").Err()
	}

	// STEP 1: Parse request.
	parsedRequest, err := updateBookRequestParser.Parse(request)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "parsing request: %v", err).Err()
	}

	// STEP 2: retrieve existing resource.
	getBookRequest := &v12.GetBookRequest{Name: request.Book.Name}
	existingBook, err := s.GetBook(ctx, getBookRequest)
	if err != nil {
		return nil, err
	}
	// Capture the Etag. If it is not set, use the latest available Etag.
	etag := request.GetBook().GetEtag()
	if etag == "" {
		etag = existingBook.GetEtag()
	}

	// STEP 3: Patch the existing resource.
	patchedBook := proto.CloneOf(existingBook)
	parsedRequest.ApplyFieldMask(patchedBook, request.Book)
	if err := protovalidate.Validate(patchedBook); err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "validating patched resource: %v", err).Err()
	}

	if request.Precondition != "" {
		ast, issues := updateBookCELEnv.Compile(request.Precondition)
		if issues != nil && issues.Err() != nil {
			return nil, status.Errorf(codes.InvalidArgument, "compiling precondition: %v", issues.Err()).Err()
		}
		if ast.OutputType() != cel.BoolType {
			return nil, status.Errorf(codes.InvalidArgument, "precondition must return bool, got %v", ast.OutputType()).Err()
		}
		prg, err := updateBookCELEnv.Program(ast)
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "creating precondition program: %v", err).Err()
		}
		out, _, err := prg.Eval(map[string]any{
			"previous_book": existingBook,
			"book":          patchedBook,
		})
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "evaluating precondition: %v", err).Err()
		}
		result, ok := out.Value().(bool)
		if !ok {
			return nil, status.Errorf(codes.Internal, "precondition returned non-bool type %T", out.Value()).Err()
		}
		if !result {
			return nil, status.Errorf(codes.FailedPrecondition, "precondition not met").Err()
		}
	}

	// Set the update time.
	patchedBook.UpdateTime = timestamppb.Now()
	{ // Compute the new Etag.
		var err error
		patchedBook.Etag, err = aip.ComputeETag(patchedBook)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "computing new etag: %v", err).Err()
		}
	}

	// STEP 4: Insert patched resource.
	bookModel, err := model.BookFromPb(patchedBook)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "converting book from pb to model: %v", err).Err()
	}
	dbBookModel, err := s.store.UpdateBook(ctx, bookModel, parsedRequest.GetSQLUpdateClause(), parsedRequest.GetSQLColumns(), etag)
	if err != nil {
		if errors.Is(err, model.ErrBookNotExist) {
			return nil, status.Errorf(codes.NotFound, "book does not exist").Err()
		}
		if errors.Is(err, model.ErrBookETagChanged) {
			return nil, status.Errorf(codes.Aborted, "ETag changed").Err()
		}
		return nil, status.FromError(err, "updating book").Err()
	}

	book, err := dbBookModel.ToPb()
	if err != nil {
		return nil, status.Errorf(codes.Internal, "converting book from model to pb: %v", err).Err()
	}

	// STEP 5: Publish events.
	{
		subject := v14.GetBookStream().GetUpdatedSubject()
		if err := subject.Publish(ctx, s.natsClient, book, existingBook, request.GetUpdateMask()); err != nil {
			return nil, status.Errorf(codes.Internal, "publishing updated event: %v", err).Err()
		}
	}
	return book, nil
}

func (s *libraryService_BookServer) publishResourceDeletedEvent(ctx context.Context, book *v14.Book) error {
	{
		subject := v14.GetBookStream().GetDeletedSubject()
		if err := subject.Publish(ctx, s.natsClient, book); err != nil {
			return status.Errorf(codes.Internal, "publishing deleted event: %v", err).Err()
		}
	}
	return nil
}

func (s *libraryService_BookServer) DeleteBook(ctx context.Context, request *v12.DeleteBookRequest) (*emptypb.Empty, error) {
	if resourcename.ContainsWildcard(request.Name) {
		return nil, status.Errorf(codes.InvalidArgument, "cannot use wildcard").Err()
	}

	// STEP 1: Parse resource name.
	organizationId, shelfId, bookId, err := model.ParseBookName(request.Name)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "parsing name: %v", err).Err()
	}

	// STEP 2: Hard delete the resource.
	dbBookModel, err := s.store.DeleteBook(ctx, organizationId, shelfId, bookId, request.GetEtag(), request.GetForce())
	if err != nil {
		if errors.Is(err, model.ErrBookNotExist) {
			if request.AllowMissing {
				return &emptypb.Empty{}, nil
			}
			return nil, status.Errorf(codes.NotFound, "book does not exist").Err()
		}
		if errors.Is(err, model.ErrBookHasChildren) {
			return nil, status.Errorf(codes.FailedPrecondition, "book has child resources; set force to delete them too").Err()
		}
		if errors.Is(err, model.ErrBookETagChanged) {
			return nil, status.Errorf(codes.Aborted, "ETag changed").Err()
		}
		return nil, status.FromError(err, "deleting book").Err()
	}

	// STEP 5: Publish event.
	book, err := dbBookModel.ToPb()
	if err != nil {
		return nil, status.Errorf(codes.Internal, "converting book from model to pb: %v", err).Err()
	}
	if err := s.publishResourceDeletedEvent(ctx, book); err != nil {
		return nil, err
	}

	return &emptypb.Empty{}, nil
}

var searchBooksRequestParser = aip.MustNewSearchRequestParser[*v12.SearchBooksRequest, *v14.Book](aip.WithFQN())

func (s *libraryService_BookServer) SearchBooks(ctx context.Context, request *v12.SearchBooksRequest) (*v12.SearchBooksResponse, error) {
	// Parse parent names
	var organizationId, shelfId string
	if err := resourcename.Sscan(request.Parent, "organizations/{organization}/shelves/{shelf}", &organizationId, &shelfId); err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "invalid parent name: %v", err).Err()
	}

	// Parse request
	parsedRequest, err := searchBooksRequestParser.Parse(request)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, err.Error()).Err()
	}
	whereClause, whereParams := parsedRequest.GetSQLWhereClause()
	var dbColumns []string

	// Retrieve from the database.
	dbBooks, dbSnippets, err := s.store.SearchBooks(ctx, organizationId, shelfId, request.IncludeSnippets, parsedRequest.GetTSQuery(), whereClause, parsedRequest.GetSQLPaginationClause(), dbColumns, whereParams...)
	if err != nil {
		return nil, status.FromError(err, "searching books").Err()
	}
	nextPageToken := parsedRequest.GetNextPageToken(len(dbBooks))
	if nextPageToken != "" {
		dbBooks = dbBooks[:len(dbBooks)-1]
		if len(dbSnippets) > 0 {
			dbSnippets = dbSnippets[:len(dbSnippets)-1]
		}
	}

	var snippets []*v15.SearchSnippet
	if request.IncludeSnippets {
		snippets = make([]*v15.SearchSnippet, len(dbBooks))
		for i := range snippets {
			snippet := &v15.SearchSnippet{}
			if dbSnippets != nil {
				if match, ok := dbSnippets[i]["title"]; ok {
					snippet.Matches = append(snippet.Matches, &v15.SearchSnippetMatch{Path: "title", Match: match})
				}
				if match, ok := dbSnippets[i]["metadata.summary"]; ok {
					snippet.Matches = append(snippet.Matches, &v15.SearchSnippetMatch{Path: "metadata.summary", Match: match})
				}
			}
			snippets[i] = snippet
		}
	}

	// Convert back to proto.
	books := make([]*v14.Book, 0, len(dbBooks))
	for _, dbBook := range dbBooks {
		book, err := dbBook.ToPb()
		if err != nil {
			return nil, status.Errorf(codes.Internal, "converting model.Book to Book: %v", err).Err()
		}
		books = append(books, book)
	}

	// Create and return response.
	return &v12.SearchBooksResponse{
		Books:         books,
		Snippets:      snippets,
		NextPageToken: nextPageToken,
	}, nil
}

