var updateBookReviewRequestParser = aip.MustNewUpdateRequestParser[*v12.UpdateBookReviewRequest, *v14.BookReview]()

func (s *libraryService_BookReviewServer) UpdateBookReview(ctx context.Context, request *v12.UpdateBookReviewRequest) (*v14.BookReview, error) {
	for {
		response, err := s.updateBookReview(ctx, request)
		if err != nil {
			if request.GetBookReview().GetEtag() == "" && status.HasCode(err, codes.Aborted) {
				// Request did not specify an ETag => we retry.
				// In order to understand why we still use ETag in the db layer, consider the following situation:
				//  > `resource.metadata` is stored as JSONB in the store.
				//  > Request A wants to update `resource.metadata.field1` and does not care about ETag.
				//  > Request B wants to update `resource.metadata.field2` and does not care about ETag.
				//  > Request A reads the resource and patches it.
				//  > Request B reads the resource and patches it.
				//  > Request A persists the patched resource, followed by Request B.
				//  > Request A's changes are lost.
				select {
				case <-ctx.Done():
					return nil, status.Errorf(codes.Canceled, "context canceled while retrying update").Err()
				default:
					continue
				}
			}
			return nil, err
		}
		return response, nil
	}
}

func (s *libraryService_BookReviewServer) updateBookReview(ctx context.Context, request *v12.UpdateBookReviewRequest) (*v14.BookReview, error) {
	if len(request.GetUpdateMask().GetPaths()) == 0 {
		return nil, status.Errorf(codes.InvalidArgument, "missing update_mask.paths").Err()
	}
	if resourcename.ContainsWildcard(request.BookReview.Name) {
		return nil, status.Errorf(codes.InvalidArgument, "cannot use wildcard").Err()
	}

	// STEP 1: Parse request.
	parsedRequest, err := updateBookReviewRequestParser.Parse(request)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "parsing request: %v", err).Err()
	}

	// STEP 2: retrieve existing resource.
	getBookReviewRequest := &v12.GetBookReviewRequest{Name: request.BookReview.Name}
	existingBookReview, err := s.GetBookReview(ctx, getBookReviewRequest)
	if err != nil {
		return nil, err
	}
	// Capture the Etag. If it is not set, use the latest available Etag.
	etag := request.GetBookReview().GetEtag()
	if etag == "" {
		etag = existingBookReview.GetEtag()
	}

	// STEP 3: Patch the existing resource.
	patchedBookReview := proto.CloneOf(existingBookReview)
	parsedRequest.ApplyFieldMask(patchedBookReview, request.BookReview)
	if err := protovalidate.Validate(patchedBookReview); err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "validating patched resource: %v", err).Err()
	}

	// Set the update time.
	patchedBookReview.UpdateTime = timestamppb.Now()
	{ // Compute the new Etag.
		var err error
		patchedBookReview.Etag, err = aip.ComputeETag(patchedBookReview)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "computing new etag: %v", err).Err()
		}
	}

	// STEP 4: Insert patched resource.
	bookReviewModel, err := model.BookReviewFromPb(patchedBookReview)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "converting bookReview from pb to model: %v", err).Err()
	}
	dbBookReviewModel, err := s.store.UpdateBookReview(ctx, bookReviewModel, parsedRequest.GetSQLUpdateClause(), parsedRequest.GetSQLColumns(), etag)
	if err != nil {
		if errors.Is(err, model.ErrBookReviewNotExist) {
			return nil, status.Errorf(codes.NotFound, "bookReview does not exist").Err()
		}
		if errors.Is(err, model.ErrBookReviewETagChanged) {
			return nil, status.Errorf(codes.Aborted, "ETag changed").Err()
		}
		return nil, status.FromError(err, "updating bookReview").Err()
	}

	bookReview, err := dbBookReviewModel.ToPb()
	if err != nil {
		return nil, status.Errorf(codes.Internal, "converting bookReview from model to pb: %v", err).Err()
	}

	return bookReview, nil
}

